// Browser side of asku: bind to the session, decrypt questions, render controls, send encrypted answers.
// The landing page renders its demo and preview with the same form components, so they can't drift from the real UI.
import "./style.css";
import DOMPurify from "dompurify";
import { marked } from "marked";
import { bindTag, checkBind, checkFragment, deriveKeys, fragmentFor, newKeyPair, open, seal, type Keys } from "../src/crypto";
// @ts-ignore generated by build.ts
import { question as validQuestion } from "./gen/validate.js";
import example from "../examples/question.json";
import { PAGES } from "./pages";

type Option = string | { value: string; label?: string; md?: string };
type Item = {
  id: string; type: "confirm" | "single" | "multi" | "text" | "number"; label: string; md?: string; required?: boolean;
  options?: Option[]; default?: any; min?: number; max?: number; step?: number;
  placeholder?: string; multiline?: boolean; maxLength?: number;
};
type Question = { title?: string; md?: string; questions: Item[] };
type Answer = { answers: Record<string, unknown>; skipped: string[]; comments: Record<string, string>; note: string; error?: string };
// pubA is unset while a session this browser created waits for its agent; pubB, T and note are only kept until then.
type State = { priv: CryptoKey; key: string; answered: number[]; pubA?: string; pubB?: string; T?: string; note?: string };
type Kid = Node | string | null | undefined | false;

const app = document.getElementById("app")!;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

function h<K extends keyof HTMLElementTagNameMap>(tag: K, props: Partial<HTMLElementTagNameMap[K]> | Record<string, unknown> = {}, ...kids: Kid[]) {
  const el = Object.assign(document.createElement(tag), props);
  el.append(...kids.filter((k): k is Node | string => k != null && k !== false));
  return el;
}

// `code` spans in plain strings become <code>.
const rich = (s: string) => s.split(/`([^`]+)`/).map((p, i) => (i % 2 ? h("code", { textContent: p }) : p));
const p = (s: string, className = "") => h("p", { className }, ...rich(s));

