// ---- reverse flow: the user starts a session here and hands the agent a link
function startCard() {
  const note = h("textarea", { rows: 4, maxLength: 10000, className: "input", placeholder: "e.g. Review my open PR and ask me anything you need to decide." });
  const err = h("p", { className: "form-err", role: "alert" });
  const btn = h("button", { type: "submit", className: "btn btn-primary btn-lg" }, icon("link"), "Create a link for my agent");
  const form = h("form", { className: "card start" },
    h("label", { className: "field" }, h("span", { className: "card-label" }, "Message for the agent", h("span", { className: "opt-tag", textContent: "Optional" })), note),
    err, btn,
    p("Your browser makes the keys. The message is encrypted before it's sent.", "fine"));
  form.onsubmit = async (e) => {
    e.preventDefault();
    btn.disabled = true;
    try {
      const b = await newKeyPair();
      const pubB = b.pub.toBase64();
      const res = await post("/s", { pub: pubB, role: "browser" });
      if (!res.ok) throw new Error(res.status === 429 ? "too many new sessions from this network, try again later" : `relay said ${res.status}`);
      const { sid, key } = await res.json();
      const st: State = { priv: b.priv, key, answered: [], pubB, T: crypto.getRandomValues(new Uint8Array(16)).toHex(), note: note.value.trim() };
      await save(sid, st);
      history.replaceState(null, "", `/a/${sid}`);
      scrollTo(0, 0);
      await waitForAgent(sid, st);
    } catch (x) {
      err.textContent = `Could not start: ${(x as Error).message}`;
      btn.disabled = false;
    }
  };
  return form;
}

async function waitForAgent(sid: string, st: State) {
  const token = Uint8Array.fromHex(st.T!);
  const link = `${location.origin}/j/${sid}#${await fragmentFor(Uint8Array.fromBase64(st.pubB!), token)}`;
  app.replaceChildren(shell([h("section", { className: "panel" },
    h("div", { className: "state-icon agent" }, icon("link")),
    h("h1", { textContent: "Give this link to your agent" }),
    p("Paste it into your chat with the agent. It joins with the asku skill (`ask join <link>`) and asks its questions right here.", "state-detail"),
    copyable(link, undefined, "Agent link"),
    live("Waiting for your agent to join…"),
    h("div", { className: "tip" }, h("p", { className: "card-label", textContent: "Agent doesn't have the skill yet? Tell it:" }), copyable(installLine(), "›")))]));

  for (;;) {
    const res = await fetch(`/s/${sid}/bind`).catch(() => null);
    if (res?.status === 404) return status("error", "This session has expired", "Start a new one to keep going.", startNew());
    if (res?.status === 200) {
      const { pub, mac } = await res.json();
      if (!(await checkBind(token, Uint8Array.fromBase64(pub), mac))) {
        drop(sid);
        return status("error", "This session is not safe", "Something other than your agent used the link. Start a new one.", startNew());
      }
      const keys = await deriveKeys(st.priv, Uint8Array.fromBase64(pub));
      await send(sid, keys, st, [0], { note: st.note ?? "" }); // the opening note is answer 0
      const joined: State = { priv: st.priv, key: st.key, answered: st.answered, pubA: pub };
      await save(sid, joined);
      return listen(sid, keys, joined);
    }
    if (res?.status !== 204) await sleep(2000);
  }
}

function listen(sid: string, keys: Keys, st: State) {
  status("wait", "Connected", "Waiting for the agent's question. This page updates by itself, keep it open.");
  const es = new EventSource(`/s/${sid}/q`);
  let cur: Open | null = null;
  let later: Batch[] = []; // arrived while an answer was being sent: they open the next form
  const done = () => {
    if (cur?.sending === false) { later.forEach(cur.add); later = []; return; } // the send failed, the form is still open
    cur = null;
    if (later.length) { const b = later; later = []; cur = render(sid, keys, st, b, done); }
  };
  // Why a batch can't join the open form. The agent client checks the same, this only guards the merged answer.
  const clash = (f: Open["f"], q: Question) => {
    const have = new Set(f.fields.map((x) => x.it.id));
    const dup = q.questions.filter((x) => have.has(x.id)).map((x) => x.id);
    return dup.length ? `ids already in the open form: ${dup.join(", ")}` : f.fields.length + q.questions.length > 50 ? "the open form would have more than 50 questions" : null;
  };
  const onQ = async (seq: number, data: string) => {
    if (st.answered.includes(seq)) return;
    let q: Question;
    try {
      q = JSON.parse(await open(keys, sid, "q", seq, JSON.parse(data)));
    } catch {
      return status("error", "A message failed verification", "It was ignored. If this repeats, ask the agent for a new link.");
    }
    const target = cur && !cur.sending ? cur : null;
    const problem = !validQuestion(q) ? (validQuestion as any).errors?.map((x: any) => `${x.instancePath || "/"} ${x.message}`).join("; ") ?? "invalid"
      : target ? clash(target.f, q) : null;
    if (problem) {
      // the batch is dropped; an open form stays as it is
      await send(sid, keys, st, [seq], { answers: {}, skipped: [], comments: {}, note: "", error: `invalid question: ${problem}`.slice(0, 2000) }).catch(() => {});
      if (cur) return;
      return status("error", "This question can't be shown", "The agent sent a form this page doesn't understand. It has been told; wait for a corrected one.", live("Waiting for the agent…"));
    }
    if (cur?.sending) later.push([seq, q]);
    else if (cur) cur.add([seq, q]);
    else cur = render(sid, keys, st, [[seq, q]], done);
  };
  let chain = Promise.resolve(); // decrypt is async: keep batches in order
  es.addEventListener("q", (e) => { chain = chain.then(() => onQ(Number(e.lastEventId), e.data)).catch(console.error); });
  es.addEventListener("close", () => {
    es.close();
    drop(sid);
    status("done", "Session ended", "The agent closed this session and the relay deleted it. You can close this tab.",
      h("div", { className: "state-actions" }, h("a", { className: "btn btn-primary", href: "/start" }, "Start a new session"), home()));
  });
  es.onerror = () => {
    if (es.readyState === EventSource.CLOSED) status("error", "This session has ended or expired", undefined, home());
  };
}

// ---- landing demos

// Pretty JSON as DOM nodes with highlight spans (built from text nodes, so typed input can't inject markup).
function jsonNodes(v: unknown) {
  const s = JSON.stringify(v, null, 2).replace(/\[\n\s*([^[\]{}]*?)\n\s*\]/g, (_, inner: string) => `[${inner.split(/,\n\s*/).join(", ")}]`);
  const out: Node[] = [];
  let last = 0;
  for (const m of s.matchAll(/("(?:\\.|[^"\\])*")(\s*:)?|\b(?:true|false|null)\b|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/g)) {
    out.push(document.createTextNode(s.slice(last, m.index)));
    const cls = m[1] ? (m[2] ? "j-key" : "j-str") : /[\d-]/.test(m[0][0]) ? "j-num" : "j-lit";
    out.push(h("span", { className: cls, textContent: m[1] ?? m[0] }));
    if (m[2]) out.push(document.createTextNode(m[2]));
    last = m.index! + m[0].length;
  }
  out.push(document.createTextNode(s.slice(last)));
  return out;
}

