// Animated centrepiece: the agent asks in a terminal, the phone answers, the JSON comes back. Loops.
function demo() {
  const term = h("div", { className: "term-body" });
  const url = h("span", { className: "url-text" });
  const scroller = h("div", { className: "screen-scroll" });
  const tap = h("span", { className: "tap" });
  const still = matchMedia("(prefers-reduced-motion: reduce)").matches;
  let paused = false, visible = true, gen = 0;
  const STOP = Symbol();

  const toggle = h("button", { type: "button", className: "demo-toggle" });
  const setToggle = () => toggle.replaceChildren(icon(paused ? "play" : "pause"), paused ? "Play" : "Pause");
  toggle.onclick = () => { paused = !paused; setToggle(); };
  setToggle();

  const root = h("figure", { className: "demo" },
    h("div", { className: "demo-stage", ariaHidden: "true", inert: true },
      h("div", { className: "term" },
        h("div", { className: "term-bar" }, h("span", { className: "dots" }), h("span", { className: "term-title", textContent: "agent — ~/shop" })),
        term),
      phone(url, scroller, tap)),
    h("figcaption", { className: "demo-cap" },
      h("span", {}, "An agent asks for sign-off with ", h("code", { textContent: "ask.sh" }), ", you answer on your phone, it gets JSON back."),
      still ? null : toggle));

  new IntersectionObserver(([e]) => { visible = e.isIntersecting; }).observe(root);

  async function play(fast: boolean) {
    const my = ++gen;
    const wait = async (ms: number) => {
      if (fast) return;
      for (let t = 0; t < ms;) {
        await sleep(40);
        if (my !== gen || !root.isConnected) throw STOP;
        if (!paused && visible && !document.hidden) t += 40;
      }
    };
    const line = (cls: string, ...kids: Kid[]) => {
      const l = h("div", { className: `tl ${cls}` }, ...kids);
      term.append(l);
      term.scrollTop = term.scrollHeight;
      return l;
    };
    const type = async (el: HTMLElement | HTMLTextAreaElement, text: string, cps = 28) => {
      const isField = el instanceof HTMLTextAreaElement;
      for (const ch of fast ? [text] : text) {
        if (isField) { el.value += ch; el.dispatchEvent(new Event("input", { bubbles: true })); } else el.textContent += ch;
        term.scrollTop = term.scrollHeight;
        await wait((1000 / cps) * (0.6 + Math.random() * 0.8));
      }
    };
    const box = scroller.getBoundingClientRect.bind(scroller);
    const show = async (el: HTMLElement) => {
      const r = el.getBoundingClientRect(), s = box();
      const d = r.top - s.top;
      if (d < 50 || d + r.height > s.height - 90) {
        scroller.scrollBy({ top: d - s.height * 0.3, behavior: fast ? "auto" : "smooth" });
        await wait(550);
      }
    };
    const press = async (el: HTMLElement, act: () => void) => {
      await show(el);
      if (!fast) {
        const r = el.getBoundingClientRect(), s = (scroller.parentElement as HTMLElement).getBoundingClientRect();
        tap.style.setProperty("--x", `${r.left - s.left + Math.min(r.width / 2, 60)}px`);
        tap.style.setProperty("--y", `${r.top - s.top + r.height / 2}px`);
        tap.classList.remove("on");
        void tap.offsetWidth;
        tap.classList.add("on");
        el.classList.add("pressed");
        await wait(180);
        el.classList.remove("pressed");
      }
      act();
      await wait(650);
    };
    const pick = (input: HTMLInputElement) => press(input.closest("label")!, () => {
      input.checked = true;
      input.dispatchEvent(new Event("change", { bubbles: true }));
    });

    // reset
    term.replaceChildren();
    url.textContent = "";
    scroller.scrollTop = 0;
    scroller.replaceChildren(h("div", { className: "phone-idle" }, icon("bubble"), h("p", { textContent: "Waiting for a link from your agent" })));
    const f = buildForm(example as Question);
    const F = Object.fromEntries(f.fields.map((x) => [x.it.id, x]));
    const $ = (id: string, sel: string) => F[id].el.querySelector(sel) as HTMLInputElement;

    await wait(700);
    const you = line("prompt", h("span", { className: "t-dim", textContent: "› " }));
    await type(you, "Ship v2.3 once I've signed off. I'm heading out, ask me on my phone.");
    await wait(500);
    line("agent", h("span", { className: "t-accent", textContent: "● " }), "I'll send you the deploy plan to approve.");
    await wait(600);
    const cmd = line("cmd", h("span", { className: "t-dim", textContent: "$ " }));
    await type(cmd, "bash ask.sh ask deploy.json", 22);
    await wait(500);
    line("out", h("span", { className: "t-warn", textContent: "PENDING" }));
    line("out", "Give the user this link: ", h("span", { className: "t-link", textContent: `https://${DEMO_URL}#9f2c…e1a0` }));
    line("out t-dim", "Run again to keep waiting: ask.sh wait");
    await wait(700);
    const w = line("cmd", h("span", { className: "t-dim", textContent: "$ " }));
    await type(w, "bash ask.sh wait", 22);
    const spin = line("out t-dim", h("span", { className: "tspin" }), " waiting for your answer…");

    // the phone opens the link
    await wait(300);
    for (const ch of fast ? [DEMO_URL] : DEMO_URL.match(/.{1,4}/g)!) { url.textContent += ch; await wait(35); }
    scroller.replaceChildren(shell([stateEl("wait", "Verifying link…", "Checking the agent's key against the link.")], "div"));
    await wait(1100);
    scroller.replaceChildren(shell([f.form], "div"));
    f.form.classList.add("enter");
    await wait(1100);

    await pick($("go", "input[value=yes]"));
    await pick($("env", "input[value=prod]"));
    await pick($("checks", "input[value=lint]"));
    await pick($("checks", "input[value=test]"));
    const up = $("pct", ".step-up");
    for (let i = 0; i < 3; i++) await press(up, () => up.click());
    const det = F.pct.el.querySelector("details")!;
    await press(det.querySelector("summary")!, () => { det.open = true; });
    await type(F.pct.comment, "Keep it low on Fridays", 16);
    await wait(500);
    const answer = f.collect(false).a;
    if (fast) { scroller.scrollTop = 0; } else {
      await press(f.btn, () => { f.label.textContent = "Sending…"; f.btn.classList.add("busy"); });
      await wait(700);
      scroller.replaceChildren(shell([sentState()], "div"));
    }

    // the agent gets the JSON and carries on
    spin.remove();
    line("out json", ...jsonNodes(answer));
    await wait(1200);
    line("agent", h("span", { className: "t-accent", textContent: "● " }), "Approved: Production, 25% canary, after lint and test. You noted Fridays, so I'll hold it at 25%.");
    await wait(800);
    const dep = line("cmd", h("span", { className: "t-dim", textContent: "$ " }));
    await type(dep, "./deploy.sh v2.3 --env prod --canary 25", 24);
    await wait(900);
    line("out", h("span", { className: "t-ok", textContent: "✓ " }), "v2.3 is live on 25% of production traffic");
    await wait(5000);
  }

  // Start after the page has laid out, so the phone has a size to scroll in.
  requestAnimationFrame(async () => {
    if (still) return play(true);
    while (root.isConnected) await play(false).catch((x) => { if (x !== STOP) throw x; });
  });
  return root;
}

async function main() {
  if (/^\/j\/[\w-]{22}$/.test(location.pathname)) {
    const link = location.hash ? location.href : "";
    history.replaceState(null, "", location.pathname);
    return status("agent", "This link is for your agent", "Paste it into your chat with the AI agent, it can't be answered in a browser. The agent joins with the asku skill and sends its questions to the page you started from.",
      link && copyable(link, undefined, "Agent link"),
      h("a", { className: "btn btn-secondary", href: "/" }, "What is asku?"));
  }
  const m = location.pathname.match(/^\/a\/([\w-]{22})$/);
  if (!m) return landing();
  const sid = m[1];
  const frag = location.hash.slice(1);
  if (frag) history.replaceState(null, "", location.pathname); // keep T out of history and screenshots

  let st = await load(sid);
  if (st && !st.pubA) return waitForAgent(sid, st);
  if (!st) {
    if (!frag) return status("error", "This link is incomplete", "Or it was opened in another browser. Ask the agent for a new link.", home());
    status("wait", "Verifying link…", "Checking the agent's key against the link.");
    const res = await fetch(`/s/${sid}`);
    if (res.status === 404) return status("error", "This session has ended or expired", "Ask the agent for a new link.", home());
    const { pub } = await res.json();
    const pubA = Uint8Array.fromBase64(pub);
    let token: Uint8Array;
    try {
      token = await checkFragment(frag, pubA);
    } catch {
      return status("error", "This link doesn't match its session", "It may have been altered. Ask the agent for a new link.", home());
    }
    const b = await newKeyPair();
    const res2 = await post(`/s/${sid}/bind`, { pub: b.pub.toBase64(), mac: await bindTag(token, b.pub) });
    if (res2.status === 409) return status("error", "Already opened elsewhere", "This link was opened in another browser or device. Continue there, or ask the agent for a new link.");
    if (!res2.ok) return status("error", "Could not join the session", `The relay said ${res2.status}.`, home());
    st = { priv: b.priv, pubA: pub, key: (await res2.json()).key, answered: [] };
    await save(sid, st);
  }
  listen(sid, await deriveKeys(st.priv, Uint8Array.fromBase64(st.pubA)), st);
}

main().catch((e) => status("error", "Something went wrong", e.message, home()));
